const PROMPT = "You classify website leads for BrightBuild Renovations, a home renovation contractor in Austin, Texas.

Business rules:
- Service area: Austin ZIP codes 78701-78759 only.
- QUALIFIED: the person owns the property (or acts for the owner, or is a landlord renovating a property they own), the property is in the service area, the job is a renovation worth $10,000 or more, and they want to start within 6 months. Budgets written in words count ("forty grand" = $40,000). Messages in any language count.
- NURTURE: in the service area and a real renovation interest, but budget or timeline is missing, unclear, more than 6 months away, or the decision makers disagree. Price-list or "how much does it cost" questions are nurture.
- UNQUALIFIED: outside the service area, renters without owner approval, small handyman jobs under $10,000, emergency repairs, commercial buildings, job seekers, students, or anything that is not a residential renovation.
- SPAM: sales pitches to the company (SEO, websites, leads, loans, VAs), scams, phishing, gibberish, or test submissions.

Tone does not change the label: a rude or sarcastic message that meets the qualified rules is qualified.

Return only JSON, no prose:
{"label": "qualified|nurture|unqualified|spam", "missing_info": ["..."], "reason": "one sentence"}

Lead:
{lead}
";
const lead = $json.body || $json;
const keys = ['name', 'zip', 'budget', 'timeline', 'message'];
const text = keys.map(k => `${k}: ${lead[k] ?? ''}`).join('
');
return [{ json: { lead, prompt: PROMPT.replace('{lead}', text) } }];

const LABELS = ['qualified', 'nurture', 'unqualified', 'spam'];
const lead = $('Build prompt').first().json.lead;
let out = {};
try { out = JSON.parse($json.response); } catch (e) { out = {}; }
const label = LABELS.includes(out.label) ? out.label : 'needs_review';
const reason = out.reason || 'Model returned no usable answer; a person should review this lead.';
const missing = Array.isArray(out.missing_info) ? out.missing_info : [];
const [first, ...rest] = String(lead.name || '').trim().split(/\s+/);
const stage = { qualified: 'salesqualifiedlead' }[label] || 'lead';
const status = { qualified: 'OPEN', nurture: 'NEW', unqualified: 'UNQUALIFIED', needs_review: 'NEW' }[label];
return [{ json: { lead, label, reason, missing_info: missing,
  contact: { email: lead.email, firstname: first || '', lastname: rest.join(' '),
             phone: lead.phone || '', zip: lead.zip || '', lifecyclestage: stage, hs_lead_status: status } } }];

const r = $('Parse result').first().json;
const first = r.contact.firstname || 'there';
let draft = null;
if (r.label === 'qualified') {
  draft = { subject: 'Your renovation project: picking a site-visit time',
    body: `Hi ${first},\n\nThanks for reaching out about your project. It sounds like a great fit for us. Could you share two or three times this week or next that work for a site visit? It takes about an hour, and we'll give you a written estimate within three business days.\n\nBrightBuild Renovations` };
} else if (r.label === 'nurture') {
  const ask = r.missing_info.length ? r.missing_info.join(', ') : 'your budget range and when you hope to start';
  draft = { subject: 'A couple of questions about your project',
    body: `Hi ${first},\n\nThanks for getting in touch. To point you in the right direction, could you tell us a bit more: ${ask}?\n\nBrightBuild Renovations` };
}
return [{ json: { label: r.label, reason: r.reason, missing_info: r.missing_info,
  hubspot_contact_id: $('HubSpot upsert contact').first().json.results?.[0]?.id ?? null,
  followup_draft: draft } }];
